const SYSTEM_FAMILY_SET = new Set(SYSTEM_FONTS.map((f) => f.family));

export const FONT_CATALOG: readonly FontEntry[] = [
  ...SYSTEM_FONTS,
  ...GOOGLE_FONTS.filter((f) => !SYSTEM_FAMILY_SET.has(f.family)),
];

export const fontsByFamily: ReadonlyMap<string, FontEntry> = new Map(
  FONT_CATALOG.map((entry) => [entry.family, entry]),
);
